pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address asserter;

    function setUp() public {
        __InvMutHandleStub stub = new __InvMutHandleStub();
        asserter = address(stub);
        c = new C(address(stub));
    }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // keep ancillaryData small so its LOG memory-copy cost cannot flip the outcome
        vm.assume(ancillaryData.length <= 32);

        // Warm c's account so cold-access (2600) gas is paid outside the capped call.
        uint256 probe = gasleft();
        address(c).balance;
        probe;
        assembly { pop(add(probe, 0)) }

        // Only the optimisticAsserter (the stub) may call requestPrice.
        vm.prank(asserter);
        (bool ok, ) = address(c).call{gas: 4000}(
            abi.encodeWithSelector(C.requestPrice.selector, identifier, time, ancillaryData)
        );

        // General rule: emitting PriceRequestAdded costs ~1500 extra gas (LOG3 = 375 + 3*375),
        // so the correct C cannot complete a requestPrice within a 4000-gas cap: ok == false.
        // The mutant's empty body needs far less gas and succeeds: ok == true.
        assertTrue(!ok);
    }
}

