import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 constant EVT = keccak256("PriceRequestAdded(bytes32,uint256,bytes)");

    function setUp() public { c = new C(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(ancillaryData.length < 256);

        vm.startPrank(address(c.optimisticAsserter()));
        vm.recordLogs();
        c.requestPrice(identifier, time, ancillaryData);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        vm.stopPrank();

        bool found = false;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == EVT) {
                found = true;
                assertTrue(uint256(logs[i].topics[1]) == uint256(identifier), "event identifier must equal the request identifier");
            }
        }
        assertTrue(found, "PriceRequestAdded must be emitted with the passed identifier");
    }
}

