pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function setUp() public { c = new C(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        address asserter = c.optimisticAsserter();

        // Rule: a request from the authorized asserter succeeds AND is recorded with
        // exactly the identifier/time/ancillaryData that were passed in.
        vm.expectEmit(true, true, false, true, address(c));
        emit PriceRequestAdded(identifier, time, ancillaryData);

        vm.prank(asserter);
        bool ok;
        try c.requestPrice(identifier, time, ancillaryData) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "requestPrice by the asserter must succeed emitting the passed identifier");
    }
}
