contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(bytes32 assertionId, bytes memory claim) public {
        // Resolve the optimistic asserter that C trusts via its public getter.
        address oa = c.optimisticAsserter();

        // Drive a price request so the unit is in a live state (must revert for non-asserter callers, so expect revert from this caller).
        bool requestOk;
        (requestOk, ) = address(c).call(
            abi.encodeWithSelector(EscalationManagerInterface.requestPrice.selector, assertionId, uint256(0), claim)
        );
        assert(!requestOk);

        // Ask the asserter to assert a truth with defaults. The asserter, acting as the trusted caller,
        // invokes c.assertionResolvedCallback(assertionId, true). On P this succeeds; on M it reverts.
        bool ok;
        (ok, ) = oa.call(
            abi.encodeWithSelector(
                OptimisticAsserterInterface.assertTruthWithDefaults.selector,
                claim,
                address(this)
            )
        );

        // GENERAL RULE: a resolution callback delivered by the trusted optimistic asserter must not revert.
        assert(ok);
    }
}

